#include <iostream>
#include <vector>
using namespace std;

// --- Fibonacci: Memoization (Top-Down) ---
int dp[101];
int fibMemo(int n) {
    if (n <= 1) return n;
    if (dp[n] != -1) return dp[n];
    return dp[n] = fibMemo(n - 1) + fibMemo(n - 2);
}

// --- Fibonacci: Tabulation (Bottom-Up) ---
int fibTab(int n) {
    vector<int> t(n + 1);
    t[0] = 0; t[1] = 1;
    for (int i = 2; i <= n; i++)
        t[i] = t[i - 1] + t[i - 2];
    return t[n];
}

int main() {
    memset(dp, -1, sizeof(dp));
    int n = 10;
    cout << "Memoization: fib(" << n << ") = " << fibMemo(n) << endl;
    cout << "Tabulation:  fib(" << n << ") = " << fibTab(n) << endl;
    return 0;
}

