#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Recursive approach (exponential)
int knapsackRec(int W, int wt[], int val[], int n) {
    if (n == 0 || W == 0) return 0;
    if (wt[n - 1] > W)
        return knapsackRec(W, wt, val, n - 1);
    return max(
        val[n - 1] + knapsackRec(W - wt[n - 1], wt, val, n - 1),
        knapsackRec(W, wt, val, n - 1)
    );
}

// DP Tabulation approach - O(N*W)
int knapsackDP(int W, int wt[], int val[], int n) {
    vector<vector<int>> dp(n + 1, vector<int>(W + 1, 0));
    for (int i = 1; i <= n; i++) {
        for (int w = 0; w <= W; w++) {
            dp[i][w] = dp[i - 1][w]; // exclude
            if (wt[i - 1] <= w)
                dp[i][w] = max(dp[i][w], val[i - 1] + dp[i - 1][w - wt[i - 1]]);
        }
    }
    return dp[n][W];
}

int main() {
    int val[] = {60, 100, 120};
    int wt[] = {10, 20, 30};
    int W = 50, n = 3;
    cout << "Max value: " << knapsackDP(W, wt, val, n) << endl; // 220
    return 0;
}

