#include <iostream>
#include <vector>
#include <climits>
using namespace std;

int matrixChainDP(int p[], int n) {
    // dp[i][j] = min cost to multiply matrices i..j
    vector<vector<int>> dp(n, vector<int>(n, 0));

    // L is chain length
    for (int L = 2; L < n; L++) {
        for (int i = 1; i < n - L + 1; i++) {
            int j = i + L - 1;
            dp[i][j] = INT_MAX;
            for (int k = i; k < j; k++) {
                int cost = dp[i][k] + dp[k + 1][j] + p[i - 1] * p[k] * p[j];
                if (cost < dp[i][j])
                    dp[i][j] = cost;
            }
        }
    }
    return dp[1][n - 1];
}

int main() {
    int p[] = {10, 20, 30, 40, 30}; // 4 matrices
    int n = 5;
    cout << "Minimum multiplications: " << matrixChainDP(p, n) << endl;
    // Output: 30000
    return 0;
}

